import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Comparison: Arrow Support vs Arrow-Native","description":"","frontmatter":{},"headers":[],"relativePath":"handl/comparison.md","filePath":"vendored/handl/comparison.md"}`),a={name:`handl/comparison.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="comparison-arrow-support-vs-arrow-native" tabindex="-1">Comparison: Arrow Support vs Arrow-Native <a class="header-anchor" href="#comparison-arrow-support-vs-arrow-native" aria-label="Permalink to “Comparison: Arrow Support vs Arrow-Native”">​</a></h1><h2 id="haskell" tabindex="-1">Haskell <a class="header-anchor" href="#haskell" aria-label="Permalink to “Haskell”">​</a></h2><p>Haskell is <strong>arrow-capable, not arrow-native</strong>.</p><p>It has:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Arrow</span></span>
<span class="line"><span>├── arr</span></span>
<span class="line"><span>├── &gt;&gt;&gt;</span></span>
<span class="line"><span>├── first</span></span>
<span class="line"><span>├── ArrowChoice</span></span>
<span class="line"><span>├── ArrowLoop</span></span>
<span class="line"><span>└── ArrowApply</span></span></code></pre></div><p>and both ordinary functions <code>(-&gt;)</code> and <code>Kleisli</code> arrows are instances. <code>ArrowApply</code> is particularly interesting because Haskell documents it as equivalent in expressive power to monads.</p><p>But Haskell&#39;s actual foundation remains:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>λ-calculus</span></span>
<span class="line"><span>  +</span></span>
<span class="line"><span>type system</span></span>
<span class="line"><span>  +</span></span>
<span class="line"><span>functions</span></span>
<span class="line"><span>  +</span></span>
<span class="line"><span>monads/etc.</span></span>
<span class="line"><span>  +</span></span>
<span class="line"><span>arrows as an abstraction</span></span></code></pre></div><p>Arrow syntax is an embedded language, not the language kernel.</p><h2 id="other-languages" tabindex="-1">Other languages <a class="header-anchor" href="#other-languages" aria-label="Permalink to “Other languages”">​</a></h2><p>There are languages and DSLs heavily based on arrows — particularly <strong>FRP, hardware description, signal-processing, parser, and dataflow DSLs</strong> — but there is no mainstream general-purpose language whose <em>core computational calculus</em> is Arrow Calculus in the way this project proposes.</p><p>That is an important distinction. There is a huge difference between:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Language supports arrows</span></span></code></pre></div><p>and:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Language IS an arrow calculus</span></span></code></pre></div><p>This project is the second.</p><h2 id="the-comparison" tabindex="-1">The comparison <a class="header-anchor" href="#the-comparison" aria-label="Permalink to “The comparison”">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Haskell</th><th>This proposal</th></tr></thead><tbody><tr><td>Functions</td><td>fundamental</td><td>derived/pure arrows</td></tr><tr><td>Lambda calculus</td><td>foundation</td><td>potentially unnecessary</td></tr><tr><td>Arrows</td><td>library/typeclass abstraction</td><td><strong>kernel</strong></td></tr><tr><td><code>&gt;&gt;&gt;</code></td><td>arrow combinator</td><td>fundamental composition</td></tr><tr><td><code>choice</code></td><td>ArrowChoice</td><td>kernel</td></tr><tr><td><code>loop</code></td><td>ArrowLoop</td><td>kernel</td></tr><tr><td><code>app</code></td><td>ArrowApply</td><td>kernel if higher-order arrows needed</td></tr><tr><td>Effects</td><td>primarily monadic, also arrows</td><td>arrow operations + handlers</td></tr><tr><td>Programs</td><td>ordinary values/terms</td><td><strong>first-class computational descriptions</strong></td></tr><tr><td>Language</td><td>fixed language</td><td><strong>first-class <code>Language</code> value</strong></td></tr><tr><td>Tooling</td><td>external ecosystem</td><td>generic protocol over <code>Language</code></td></tr></tbody></table><h2 id="the-research-gap" tabindex="-1">The research gap <a class="header-anchor" href="#the-research-gap" aria-label="Permalink to “The research gap”">​</a></h2><p>The interesting research gap is therefore not <em>&quot;Haskell has arrows, so why another language?&quot;</em></p><p>It is:</p><blockquote><p><strong>What happens if we take what Haskell treats as an embedded Arrow abstraction and make it the foundational computational calculus of the language — and then make the language itself first-class?</strong></p></blockquote><p>That is a much stronger and, as far as this survey goes, substantially less explored design point.</p>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};